mapper.update:
UPDATE stock
INNER JOIN sku
    ON sku.id = stock.sku_id
SET
    stock.available_quantity = stock.available_quantity - #{quantity},
    stock.reserved_quantity = stock.reserved_quantity + #{quantity},
    stock.version = stock.version + 1,
    stock.updated_at = #{updatedAt}
WHERE sku.sku_code = #{skuCode}
  AND stock.available_quantity >= #{quantity}
